from collections import deque
class TreeNode:
    def __init__(self, value, left=None, right=None): self.value, self.left, self.right = value, left, right

def preorder(root):
    return [] if root is None else [root.value] + preorder(root.left) + preorder(root.right)
def inorder(root):
    return [] if root is None else inorder(root.left) + [root.value] + inorder(root.right)
def postorder(root):
    return [] if root is None else postorder(root.left) + postorder(root.right) + [root.value]
def level_order(root):
    result, q = [], deque([root] if root else [])
    while q:
        node=q.popleft(); result.append(node.value)
        if node.left: q.append(node.left)
        if node.right: q.append(node.right)
    return result

root=TreeNode(2,TreeNode(1),TreeNode(3))
assert preorder(root)==[2,1,3] and inorder(root)==[1,2,3] and postorder(root)==[1,3,2] and level_order(root)==[2,1,3]
